// Turns Bob's board map file into the base pack's board file (packs/base/board/spaces.json),
// the one the game reads (DEC-240). Only a finished map is turned: every space completed and
// no check error other than a missing region.
import { buildingOf, checkDraft, neighboursOf, SLOT_ORDER, terrainOf } from "./model.mjs";

export const DRAFT_NOTE =
  "Generated by apps/board-map-tool (pnpm export-pack) from the board map file. Do not edit by hand. " +
  "Compass slots are tower-relative: N on every space points at the tower.";

// Placed neighbours clockwise from N, then the ones under the cross by id. The game fills those
// into the first open slot in this order.
function orderNeighbours(list) {
  const rank = (n) => (n.slot === null ? SLOT_ORDER.length : SLOT_ORDER.indexOf(n.slot));
  return [...list].sort((a, b) => rank(a) - rank(b) || a.to.localeCompare(b.to));
}

// Returns { board } or { problems } when the map is not ready to ship.
export function toPackBoard(draft, spaces) {
  const problems = [];
  const open = spaces.filter((s) => !draft.completed?.[s.id]).map((s) => s.id);
  if (open.length) problems.push(`not completed in the tool: ${open.join(", ")}`);
  const { errors } = checkDraft(draft, spaces);
  problems.push(...errors.filter((e) => !e.endsWith("has no region")));
  if (problems.length) return { problems };

  const board = {
    draft_note: DRAFT_NOTE,
    region_labels: draft.regions.map((r) => ({ id: r.id, name: r.name })),
    spaces: spaces.map((s) => {
      const neighbours = orderNeighbours(neighboursOf(draft, s.id)).map((n) => ({
        to: n.to,
        slot: n.slot,
      }));
      const building = buildingOf(draft, s);
      return {
        id: s.id,
        name: s.name,
        kingdom: s.kingdom,
        terrain: terrainOf(draft, s).toLowerCase(),
        ...(building ? { building: building.toLowerCase() } : {}),
        ...(draft.objects?.[s.id]?.tower ? { tower_adjacent: true } : {}),
        ...(draft.regionOf[s.id] ? { region: draft.regionOf[s.id] } : {}),
        adjacent: neighbours.map((n) => n.to).sort(),
        neighbours,
      };
    }),
  };
  return { board };
}
